import type { AcousticFrame } from '../../core/entities/AcousticFeature.js';

export interface RecorderCallbacks {
  onStartRecord: () => void;
  onStopRecord: () => void;
  onGenerateArchive: () => void;
}

export class AudioRecorderControl {
  private element: HTMLElement;
  private callbacks: RecorderCallbacks;
  private isRecording: boolean = false;

  private recordBtn: HTMLButtonElement;
  private btnTitle: HTMLElement;
  private btnHint: HTMLElement;
  private genArchiveBtn: HTMLButtonElement;

  // 遥测元素
  private valPitch: HTMLElement;
  private valTempo: HTMLElement;
  private valPause: HTMLElement;
  private valVolume: HTMLElement;
  private meterVolume: HTMLElement;

  constructor(callbacks: RecorderCallbacks) {
    this.callbacks = callbacks;
    this.element = document.createElement('div');
    this.element.className = 'recording-dock';

    this.element.innerHTML = `
      <div class="record-btn-wrapper">
        <button class="record-btn" id="record-trigger-btn" title="点击开始/停止录音">
          <span id="record-icon">🎙️</span>
        </button>
        <div class="record-btn-text-box">
          <span class="record-btn-title" id="record-title">开始凝固声音</span>
          <span class="record-btn-hint" id="record-hint">对着麦克风说话，特征将实时沉降</span>
        </div>
      </div>

      <div class="live-telemetry-bar">
        <div class="telemetry-item">
          <span class="telemetry-label">语调音高 (F0)</span>
          <span class="telemetry-value" id="val-pitch">-- Hz</span>
        </div>
        <div class="telemetry-item">
          <span class="telemetry-label">音节语速</span>
          <span class="telemetry-value" id="val-tempo">0.0 /s</span>
        </div>
        <div class="telemetry-item">
          <span class="telemetry-label">静音停顿</span>
          <span class="telemetry-value" id="val-pause">--</span>
        </div>
        <div class="telemetry-item">
          <span class="telemetry-label">起伏动量</span>
          <span class="telemetry-value" id="val-vol">0%</span>
          <div class="telemetry-meter">
            <div class="telemetry-meter-bar" id="meter-volume"></div>
          </div>
        </div>
      </div>

      <div class="console-actions">
        <button class="btn-primary" id="btn-generate-archive" style="display: none;">
          <span>📜</span> 结晶为地质档案
        </button>
      </div>
    `;

    this.recordBtn = this.element.querySelector('#record-trigger-btn') as HTMLButtonElement;
    this.btnTitle = this.element.querySelector('#record-title') as HTMLElement;
    this.btnHint = this.element.querySelector('#record-hint') as HTMLElement;
    this.genArchiveBtn = this.element.querySelector('#btn-generate-archive') as HTMLButtonElement;

    this.valPitch = this.element.querySelector('#val-pitch') as HTMLElement;
    this.valTempo = this.element.querySelector('#val-tempo') as HTMLElement;
    this.valPause = this.element.querySelector('#val-pause') as HTMLElement;
    this.valVolume = this.element.querySelector('#val-vol') as HTMLElement;
    this.meterVolume = this.element.querySelector('#meter-volume') as HTMLElement;

    this.initEvents();
  }

  public getElement(): HTMLElement {
    return this.element;
  }

  public setRecordingState(recording: boolean): void {
    this.isRecording = recording;
    const icon = this.element.querySelector('#record-icon');

    if (recording) {
      this.recordBtn.classList.add('recording');
      if (icon) icon.textContent = '⏹️';
      this.btnTitle.textContent = '正在结晶沉降...';
      this.btnHint.textContent = '点击按钮完成录音并凝固岩层';
      this.genArchiveBtn.style.display = 'none';
    } else {
      this.recordBtn.classList.remove('recording');
      if (icon) icon.textContent = '🎙️';
      this.btnTitle.textContent = '开始凝固声音';
      this.btnHint.textContent = '对着麦克风说话，特征将实时沉降';
    }
  }

  public enableArchiveButton(visible: boolean): void {
    this.genArchiveBtn.style.display = visible ? 'inline-flex' : 'none';
  }

  public updateTelemetry(frame: AcousticFrame, currentTempo: number): void {
    if (!this.isRecording) return;

    // 音高
    if (frame.isVoiced && frame.pitch > 0) {
      this.valPitch.textContent = `${Math.round(frame.pitch)} Hz`;
      this.valPitch.classList.add('active');
    } else {
      this.valPitch.textContent = '浊音未启';
      this.valPitch.classList.remove('active');
    }

    // 语速
    this.valTempo.textContent = `${currentTempo.toFixed(1)} /s`;

    // 停顿
    if (frame.isSilence) {
      this.valPause.textContent = '静音深思';
      this.valPause.style.color = '#94a3b8';
    } else {
      this.valPause.textContent = '声浪发声';
      this.valPause.style.color = '#38bdf8';
    }

    // 音量与进度条
    const volPercent = Math.min(100, Math.round(frame.rms * 300));
    this.valVolume.textContent = `${volPercent}%`;
    this.meterVolume.style.width = `${volPercent}%`;
  }

  private initEvents(): void {
    this.recordBtn.addEventListener('click', () => {
      if (this.isRecording) {
        this.callbacks.onStopRecord();
      } else {
        this.callbacks.onStartRecord();
      }
    });

    this.genArchiveBtn.addEventListener('click', () => {
      this.callbacks.onGenerateArchive();
    });
  }
}

