import type { AcousticFrame } from '../core/entities/AcousticFeature.js';
import type { StratumLayer } from '../core/entities/StratumLayer.js';
import type { VoiceGeologyArchive } from '../core/entities/GeologyArchive.js';

import { StratumSynthesizer } from '../core/algorithms/StratumSynthesizer.js';
import { WebAudioInputAdapter } from '../adapters/audio/WebAudioInputAdapter.js';
import { WebAudioEchoPlayerAdapter } from '../adapters/audio/WebAudioEchoPlayerAdapter.js';
import { CanvasStrataRenderer } from '../adapters/graphics/CanvasStrataRenderer.js';
import { LocalArchiveRepository } from '../adapters/storage/LocalArchiveRepository.js';

import { HeaderComponent } from './components/Header.js';
import { EchoWallView } from './components/EchoWallView.js';
import { AudioRecorderControl } from './components/AudioRecorderControl.js';
import { StratumDetailModal } from './components/StratumDetailModal.js';
import { GeologyArchiveCard } from './components/GeologyArchiveCard.js';
import { ArchiveHistoryDrawer } from './components/ArchiveHistoryDrawer.js';

/**
 * 表现层总装配器 (Composition Root)
 * 严格遵循依赖注入与分层架构，组装核心算法、输入/输出适配器及视图界面
 */
export class App {
  private rootElement: HTMLElement;

  // 核心领域
  private stratumSynthesizer: StratumSynthesizer;

  // 端口适配器
  private audioInputAdapter: WebAudioInputAdapter;
  private echoPlayerAdapter: WebAudioEchoPlayerAdapter;
  private strataRendererAdapter: CanvasStrataRenderer;
  private archiveRepository: LocalArchiveRepository;

  // UI 组件
  private headerComponent: HeaderComponent;
  private echoWallView: EchoWallView;
  private recorderControl: AudioRecorderControl;
  private stratumModal: StratumDetailModal;
  private archiveCard: GeologyArchiveCard;
  private historyDrawer: ArchiveHistoryDrawer;

  // 运行期会话数据
  private liveFrames: AcousticFrame[] = [];
  private currentStrata: StratumLayer[] = [];
  private currentArchive: VoiceGeologyArchive | null = null;
  private samplePresetIndex: number = 0;

  constructor(rootElement: HTMLElement) {
    this.rootElement = rootElement;
    this.rootElement.innerHTML = '';

    // 1. 初始化核心领域服务
    this.stratumSynthesizer = new StratumSynthesizer();

    // 2. 初始化适配器
    this.audioInputAdapter = new WebAudioInputAdapter();
    this.echoPlayerAdapter = new WebAudioEchoPlayerAdapter();
    this.strataRendererAdapter = new CanvasStrataRenderer();
    this.archiveRepository = new LocalArchiveRepository();

    // 3. 构建子组件并绑定依赖
    this.headerComponent = new HeaderComponent({
      onLoadSample: () => this.handleLoadNextSample(),
      onOpenHistory: () => this.historyDrawer.open(),
      onShowAbout: () => this.showAboutModal(),
    });

    this.echoWallView = new EchoWallView(this.strataRendererAdapter, {
      onStratumSelect: (stratum) => this.handleSelectStratum(stratum),
    });

    this.recorderControl = new AudioRecorderControl({
      onStartRecord: () => this.handleStartRecord(),
      onStopRecord: () => this.handleStopRecord(),
      onGenerateArchive: () => this.handleGenerateArchive(),
    });

    this.stratumModal = new StratumDetailModal(this.echoPlayerAdapter);

    this.archiveCard = new GeologyArchiveCard({
      onSaveArchive: (arc) => this.archiveRepository.saveArchive(arc),
      onClose: () => {},
    });

    this.historyDrawer = new ArchiveHistoryDrawer(this.archiveRepository, {
      onSelectArchive: (arc) => this.loadArchiveIntoView(arc),
    });

    // 4. 挂载到根 DOM
    this.mount();

    // 5. 绑定实时音频采集流与回放事件
    this.bindEvents();

    // 6. 载入初始地质样本，提供立即沉浸式体验
    this.initDefaultView();
  }

  private mount(): void {
    this.rootElement.appendChild(this.headerComponent.getElement());
    this.rootElement.appendChild(this.echoWallView.getElement());
    this.rootElement.appendChild(this.recorderControl.getElement());
    this.rootElement.appendChild(this.stratumModal.getElement());
    this.rootElement.appendChild(this.archiveCard.getElement());
    this.rootElement.appendChild(this.historyDrawer.getElement());
  }

  private bindEvents(): void {
    // 麦克风瞬时声学帧回调
    this.audioInputAdapter.onFrame((frame) => {
      this.liveFrames.push(frame);

      // 更新实时仪表盘
      const tempoRate = this.calculateInstantTempo();
      this.recorderControl.updateTelemetry(frame, tempoRate);

      // 通知画布实时起伏
      this.strataRendererAdapter.setOptions({
        activeLiveFrame: frame,
        isRecording: true,
      });
    });

    // 麦克风录制状态变更
    this.audioInputAdapter.onStateChange((capturing) => {
      this.recorderControl.setRecordingState(capturing);
      this.strataRendererAdapter.setOptions({
        isRecording: capturing,
      });
    });

    // 回声合成播放器状态监听（同步回声壁上的波阵面动画）
    this.echoPlayerAdapter.onStateChange((isPlaying, stratumId) => {
      this.strataRendererAdapter.setOptions({
        playbackStratumId: isPlaying ? stratumId : null,
      });
    });
  }

  private async initDefaultView(): Promise<void> {
    const presets = this.archiveRepository.getPresetSampleArchives();
    if (presets.length > 0) {
      this.loadArchiveIntoView(presets[0]);
    }
  }

  private async handleStartRecord(): Promise<void> {
    try {
      this.liveFrames = [];
      await this.audioInputAdapter.start();
    } catch (err) {
      alert(`麦克风启动失败：${err instanceof Error ? err.message : String(err)}`);
    }
  }

  private handleStopRecord(): void {
    this.audioInputAdapter.stop();

    if (this.liveFrames.length > 10) {
      // 核心算法：将连续的物理声学流凝固为地质岩层
      const generatedStrata = this.stratumSynthesizer.segmentIntoStrata(this.liveFrames);
      if (generatedStrata.length > 0) {
        this.currentStrata = generatedStrata;
        this.echoWallView.updateStrata(this.currentStrata);
        this.recorderControl.enableArchiveButton(true);

        // 自动装配声音地质档案
        this.currentArchive = this.stratumSynthesizer.assembleArchive(
          this.currentStrata,
          `我的声音地质档案 · ${new Date().toLocaleTimeString()}`
        );
      }
    } else {
      alert('录制时间过短，未能沉积足够特征的声学岩层。请对着麦克风说一两句话再试。');
    }
  }

  private handleGenerateArchive(): void {
    if (!this.currentArchive && this.currentStrata.length > 0) {
      this.currentArchive = this.stratumSynthesizer.assembleArchive(this.currentStrata);
    }

    if (this.currentArchive) {
      this.archiveCard.open(this.currentArchive);
    }
  }

  private handleSelectStratum(stratum: StratumLayer): void {
    this.strataRendererAdapter.setOptions({ selectedStratumId: stratum.id });
    this.stratumModal.open(stratum);
  }

  private loadArchiveIntoView(archive: VoiceGeologyArchive): void {
    this.currentArchive = archive;
    this.currentStrata = archive.strata;
    this.echoWallView.updateStrata(archive.strata);
    this.recorderControl.enableArchiveButton(true);
  }

  private handleLoadNextSample(): void {
    const presets = this.archiveRepository.getPresetSampleArchives();
    this.samplePresetIndex = (this.samplePresetIndex + 1) % presets.length;
    const selectedPreset = presets[this.samplePresetIndex];
    this.loadArchiveIntoView(selectedPreset);
  }

  private calculateInstantTempo(): number {
    if (this.liveFrames.length < 5) return 0;
    const recent = this.liveFrames.slice(-30);
    const onsetCount = recent.filter(f => f.onsetEnergy && f.onsetEnergy > 0).length;
    const durSec = (recent[recent.length - 1].timestamp - recent[0].timestamp) / 1000;
    return durSec > 0 ? Number((onsetCount / durSec).toFixed(1)) : 0;
  }

  private showAboutModal(): void {
    const modal = document.createElement('div');
    modal.className = 'modal-backdrop open';
    modal.innerHTML = `
      <div class="modal-card">
        <div class="modal-header">
          <div class="modal-title-wrap">
            <h3 class="modal-title">声波地质学 · 情绪回声壁</h3>
            <span class="modal-subtitle">Pure Frontend Acoustic Geology Architecture</span>
          </div>
          <button class="close-btn" id="about-close">&times;</button>
        </div>
        <div style="font-size: 0.9rem; line-height: 1.7; color: #d1d5db; margin-bottom: 18px;">
          <p style="margin-bottom: 12px;">
            <strong>情绪回声壁</strong> 是一次声音隐私与物理可视化的艺术探索：
          </p>
          <ul style="padding-left: 20px; margin-bottom: 14px; display: flex; flex-direction: column; gap: 8px;">
            <li>🛡️ <strong>零原始语音存储</strong>：系统只通过自相关与频谱分析提取语调起伏、语速律动、停顿频率与能量动态，即刻销毁时域声波，绝不录制任何语音或语义内容。</li>
            <li>🎨 <strong>声波凝固为岩层</strong>：语调驱动山脊褶皱，音量与时长决定岩层厚度，情绪效价与唤醒度生成专属彩色矿物色谱（火成岩、沉积岩、变质岩）。</li>
            <li>🎵 <strong>抽象声学情绪回放</strong>：点击任意岩层，由纯纯合成器根据原声曲线驱动谐波音律，带给你如矿物共鸣般的情绪回响，无任何字词泄露！</li>
            <li>📐 <strong>高内聚低耦合分层架构</strong>：核心领域层 (Domain) + 端口层 (Ports) + 适配器层 (Adapters) + 原生 CSS 表现层。</li>
          </ul>
        </div>
        <div class="modal-footer" style="justify-content: flex-end;">
          <button class="btn-primary" id="about-ok">我知道了</button>
        </div>
      </div>
    `;

    document.body.appendChild(modal);
    const close = () => {
      modal.remove();
    };
    modal.querySelector('#about-close')?.addEventListener('click', close);
    modal.querySelector('#about-ok')?.addEventListener('click', close);
    modal.addEventListener('click', (e) => {
      if (e.target === modal) close();
    });
  }
}

import type { AcousticFrame } from '../core/entities/AcousticFeature.js';

export type AcousticFrameListener = (frame: AcousticFrame) => void;
export type StateChangeListener = (isCapturing: boolean) => void;

/**
 * 麦克风音频采集与物理分析端口规范
 */
export interface IAudioInputPort {
  /**
   * 请求麦克风授权并启动声学采集流
   */
  start(): Promise<void>;

  /**
   * 停止麦克风采集并释放硬件资源
   */
  stop(): void;

  /**
   * 注册声学瞬时特征帧回调
   */
  onFrame(listener: AcousticFrameListener): () => void;

  /**
   * 注册采集状态变更回调
   */
  onStateChange(listener: StateChangeListener): () => void;

  /**
   * 当前是否处于采集监听中
   */
  isCapturing(): boolean;
}

