import type { StratumLayer } from '../../core/entities/StratumLayer.js';
import type { IEchoPlaybackPort } from '../../ports/IEchoPlaybackPort.js';

export class StratumDetailModal {
  private element: HTMLElement;
  private echoPlayer: IEchoPlaybackPort;
  private currentStratum: StratumLayer | null = null;
  private isPlaying: boolean = false;

  private modalTitle: HTMLElement;
  private modalSubtitle: HTMLElement;
  private samplePreview: HTMLElement;
  private statPitch: HTMLElement;
  private statTempo: HTMLElement;
  private statPause: HTMLElement;
  private statVolume: HTMLElement;
  private statVariance: HTMLElement;
  private statDominance: HTMLElement;
  private curveCanvas: HTMLCanvasElement;
  private replayBtn: HTMLButtonElement;
  private replayText: HTMLElement;

  constructor(echoPlayer: IEchoPlaybackPort) {
    this.echoPlayer = echoPlayer;
    this.element = document.createElement('div');
    this.element.className = 'modal-backdrop';

    this.element.innerHTML = `
      <div class="modal-card">
        <div class="modal-header">
          <div class="modal-title-wrap">
            <h3 class="modal-title" id="modal-stratum-title">岩层定名</h3>
            <span class="modal-subtitle" id="modal-stratum-subtitle">情绪地质学特征探针</span>
          </div>
          <button class="close-btn" id="modal-close-btn" title="关闭">&times;</button>
        </div>

        <div class="stratum-sample-preview" id="sample-preview">
          岩层矿物切片预览
        </div>

        <div class="modal-grid-stats">
          <div class="stat-box">
            <span class="stat-label">基频音高</span>
            <span class="stat-val" id="stat-pitch">-- Hz</span>
          </div>
          <div class="stat-box">
            <span class="stat-label">语速脉冲</span>
            <span class="stat-val" id="stat-tempo">-- /s</span>
          </div>
          <div class="stat-box">
            <span class="stat-label">停顿沉思比</span>
            <span class="stat-val" id="stat-pause">-- %</span>
          </div>
          <div class="stat-box">
            <span class="stat-label">能量幅度</span>
            <span class="stat-val" id="stat-volume">--</span>
          </div>
          <div class="stat-box">
            <span class="stat-label">音调离散起伏</span>
            <span class="stat-val" id="stat-var">--</span>
          </div>
          <div class="stat-box">
            <span class="stat-label">意志支配度</span>
            <span class="stat-val" id="stat-dom">--</span>
          </div>
        </div>

        <div style="font-size: 0.75rem; color: var(--text-muted); margin-bottom: 6px;">
          声学微观音律轨迹 (脱敏后纯基频走势)
        </div>
        <canvas class="acoustic-curve-canvas" id="curve-canvas"></canvas>

        <div class="modal-footer">
          <div style="font-size: 0.78rem; color: #64ffda;">
            🔒 绝无任何语音内容外泄 · 纯声学情绪抽象共鸣
          </div>
          <button class="replay-sound-btn" id="btn-replay-echo">
            <span id="replay-icon">🔊</span>
            <span id="replay-text">回放声学情绪</span>
          </button>
        </div>
      </div>
    `;

    this.modalTitle = this.element.querySelector('#modal-stratum-title') as HTMLElement;
    this.modalSubtitle = this.element.querySelector('#modal-stratum-subtitle') as HTMLElement;
    this.samplePreview = this.element.querySelector('#sample-preview') as HTMLElement;
    this.statPitch = this.element.querySelector('#stat-pitch') as HTMLElement;
    this.statTempo = this.element.querySelector('#stat-tempo') as HTMLElement;
    this.statPause = this.element.querySelector('#stat-pause') as HTMLElement;
    this.statVolume = this.element.querySelector('#stat-volume') as HTMLElement;
    this.statVariance = this.element.querySelector('#stat-var') as HTMLElement;
    this.statDominance = this.element.querySelector('#stat-dom') as HTMLElement;
    this.curveCanvas = this.element.querySelector('#curve-canvas') as HTMLCanvasElement;
    this.replayBtn = this.element.querySelector('#btn-replay-echo') as HTMLButtonElement;
    this.replayText = this.element.querySelector('#replay-text') as HTMLElement;

    this.initEvents();
  }

  public getElement(): HTMLElement {
    return this.element;
  }

  public open(stratum: StratumLayer): void {
    this.currentStratum = stratum;

    this.modalTitle.textContent = stratum.geologicalName;
    this.modalSubtitle.textContent = `${stratum.emotion.primaryEmotion} · 时长 ${stratum.duration}s`;

    // 渐变预览
    const p = stratum.emotion.palette;
    this.samplePreview.style.background = `linear-gradient(90deg, ${p.primary}, ${p.secondary}, ${p.shadow})`;
    this.samplePreview.style.color = '#ffffff';
    this.samplePreview.textContent = stratum.geologicalDescription;

    this.statPitch.textContent = `${stratum.avgPitch} Hz`;
    this.statTempo.textContent = `${stratum.tempoRate} /s`;
    this.statPause.textContent = `${Math.round(stratum.pauseRatio * 100)} %`;
    this.statVolume.textContent = stratum.avgVolume.toFixed(3);
    this.statVariance.textContent = `±${stratum.pitchVariance} Hz`;
    this.statDominance.textContent = `${Math.round(stratum.emotion.dominance * 100)} %`;

    this.drawCurve(stratum);

    this.element.classList.add('open');
    this.updateReplayButtonState(false);
  }

  public close(): void {
    if (this.isPlaying) {
      this.echoPlayer.stop();
    }
    this.element.classList.remove('open');
    this.currentStratum = null;
  }

  private drawCurve(stratum: StratumLayer): void {
    const canvas = this.curveCanvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);

    const w = rect.width;
    const h = rect.height;

    // 清屏
    ctx.fillStyle = '#0b0e14';
    ctx.fillRect(0, 0, w, h);

    const traj = stratum.acousticTrajectory;
    if (!traj || traj.length < 2) return;

    ctx.strokeStyle = stratum.emotion.palette.glow;
    ctx.lineWidth = 2;
    ctx.beginPath();

    let minP = Infinity;
    let maxP = -Infinity;
    traj.forEach(pt => {
      const p = pt.pitch > 0 ? pt.pitch : stratum.avgPitch;
      if (p < minP) minP = p;
      if (p > maxP) maxP = p;
    });
    if (maxP <= minP) {
      maxP = minP + 50;
      minP = Math.max(50, minP - 20);
    }

    const dur = stratum.duration || 1;

    for (let i = 0; i < traj.length; i++) {
      const pt = traj[i];
      const p = pt.pitch > 0 ? pt.pitch : stratum.avgPitch;
      const x = (pt.timeOffset / dur) * w;
      const y = h - ((p - minP) / (maxP - minP)) * (h - 16) - 8;

      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }

    ctx.stroke();

    // 阴影发光
    ctx.shadowColor = stratum.emotion.palette.glow;
    ctx.shadowBlur = 8;
  }

  private initEvents(): void {
    this.element.querySelector('#modal-close-btn')?.addEventListener('click', () => this.close());
    this.element.addEventListener('click', (e) => {
      if (e.target === this.element) this.close();
    });

    this.replayBtn.addEventListener('click', async () => {
      if (!this.currentStratum) return;

      if (this.isPlaying) {
        this.echoPlayer.stop();
        this.updateReplayButtonState(false);
      } else {
        this.updateReplayButtonState(true);
        await this.echoPlayer.play(
          this.currentStratum,
          undefined,
          () => {
            this.updateReplayButtonState(false);
          }
        );
      }
    });
  }

  private updateReplayButtonState(playing: boolean): void {
    this.isPlaying = playing;
    if (playing) {
      this.replayBtn.classList.add('playing');
      this.replayText.textContent = '共鸣回响中...';
    } else {
      this.replayBtn.classList.remove('playing');
      this.replayText.textContent = '回放声学情绪';
    }
  }
}

