/* ========================================================
   1. 顶部导航与状态条 (Header)
   ======================================================== */
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 28px;
  background: var(--bg-surface);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--bg-glass-border);
  position: sticky;
  top: 0;
  z-index: 40;
}

.brand-section {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: linear-gradient(135deg, #0288d1, #ff5722);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 12px rgba(2, 136, 209, 0.35);
  font-size: 20px;
}

.brand-title {
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.brand-title .en-sub {
  font-size: 0.8rem;
  font-weight: 400;
  color: var(--text-secondary);
  letter-spacing: 1px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn-secondary {
  padding: 8px 14px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--bg-glass-border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.85rem;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.2);
}

.privacy-badge {
  font-size: 0.75rem;
  padding: 4px 10px;
  background: rgba(0, 191, 165, 0.12);
  border: 1px solid rgba(0, 191, 165, 0.3);
  color: #64ffda;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  gap: 5px;
}

.privacy-badge .dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #64ffda;
  box-shadow: 0 0 8px #64ffda;
}

/* ========================================================
   2. 回声壁舞台 (Echo Wall Stage)
   ======================================================== */
.wall-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 20px 28px 120px 28px;
  position: relative;
  min-height: calc(100vh - 200px);
}

.wall-header-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}

.wall-title-box {
  display: flex;
  align-items: center;
  gap: 10px;
}

.wall-title {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.wall-status-chip {
  font-size: 0.75rem;
  padding: 2px 8px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-secondary);
  font-family: var(--font-mono);
}

.wall-canvas-wrapper {
  position: relative;
  flex: 1;
  min-height: 440px;
  background: #090c13;
  border: 1px solid var(--bg-glass-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: inset 0 2px 10px rgba(0, 0, 0, 0.8), var(--shadow-md);
}

.wall-canvas {
  width: 100%;
  height: 100%;
  display: block;
  cursor: crosshair;
}

.wall-hover-tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(18, 23, 34, 0.92);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  color: #ffffff;
  font-size: 0.8rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.6);
  z-index: 30;
  transform: translate(-50%, -120%);
  transition: opacity 0.15s ease;
  white-space: nowrap;
}

.wall-hover-tooltip .tip-rock {
  font-weight: 600;
  color: #38bdf8;
  margin-bottom: 2px;
}

.wall-hover-tooltip .tip-meta {
  color: var(--text-secondary);
  font-size: 0.72rem;
}

/* ========================================================
   3. 底部录制与物理控制台 (Recording Console Dock)
   ======================================================== */
.recording-dock {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 50;
  width: calc(100% - 56px);
  max-width: 880px;
  background: rgba(18, 23, 34, 0.88);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 20px;
  padding: 12px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.75), 0 0 0 1px rgba(255, 255, 255, 0.05);
}

.record-btn-wrapper {
  display: flex;
  align-items: center;
  gap: 16px;
}

.record-btn {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background: linear-gradient(135deg, #ef4444, #b91c1c);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  box-shadow: 0 4px 16px rgba(239, 68, 68, 0.4);
  position: relative;
}

.record-btn:hover {
  transform: scale(1.05);
  box-shadow: 0 6px 22px rgba(239, 68, 68, 0.55);
}

.record-btn.recording {
  background: linear-gradient(135deg, #ff5722, #d81b60);
  animation: pulse-ring 1.8s infinite;
}

.record-btn-text-box {
  display: flex;
  flex-direction: column;
}

.record-btn-title {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-primary);
}

.record-btn-hint {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* 实时声学指标仪表条 (Telemetry) */
.live-telemetry-bar {
  display: flex;
  align-items: center;
  gap: 18px;
}

.telemetry-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.telemetry-label {
  font-size: 0.7rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.telemetry-value {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-accent);
}

.telemetry-value.active {
  color: #ff5722;
}

.telemetry-meter {
  width: 46px;
  height: 4px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  overflow: hidden;
  margin-top: 3px;
}

.telemetry-meter-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #00b0ff, #ff5722);
  transition: width 0.08s ease;
}

.console-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.btn-primary {
  padding: 9px 18px;
  background: linear-gradient(135deg, #0288d1, #0097a7);
  border: none;
  border-radius: var(--radius-sm);
  color: #ffffff;
  font-size: 0.88rem;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 4px 14px rgba(2, 136, 209, 0.35);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #039be5, #00acc1);
  transform: translateY(-1px);
  box-shadow: 0 6px 18px rgba(2, 136, 209, 0.45);
}

/* ========================================================
   4. 单个岩层情绪回响探针 (Stratum Detail Modal)
   ======================================================== */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 20px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}

.modal-backdrop.open {
  opacity: 1;
  pointer-events: auto;
}

.modal-card {
  background: var(--bg-surface-elevated);
