```ts
public async preflightCheck(): Promise<void> {
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    throw new Error('当前浏览器环境不支持麦克风采集，请使用 HTTPS 或 localhost 访问');
  }
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
    // 探测成功立即释放硬件，正式录音时会重新开启
    stream.getTracks().forEach(track => track.stop());
  } catch (err) {
    throw new Error(this.describeMicError(err));
  }
}

private describeMicError(err: unknown): string {
  if (err instanceof DOMException) {
    switch (err.name) {
      case 'NotAllowedError':
      case 'SecurityError':
        return '麦克风权限被拒绝，请在浏览器地址栏的站点设置中允许麦克风后重新检测';
      case 'NotFoundError':
      case 'OverconstrainedError':
        return '未检测到可用的麦克风设备，请确认麦克风已连接';
      case 'NotReadableError':
      case 'AbortError':
        return '麦克风被其他应用占用，请关闭占用程序后重新检测';
      default:
        return err.message || '未知麦克风错误';
    }
  }
  return err instanceof Error ? err.message : String(err);
}
```

