export interface RecordingPrepCallbacks {
  /** 探测麦克风权限与设备可用性，失败时抛出带用户可读信息的 Error */
  checkMicrophone: () => Promise<void>;
  /** 用户确认开始，正式进入结晶沉降录音 */
  onConfirm: () => void;
}

type MicStatus = 'checking' | 'ready' | 'error';

export class RecordingPrepModal {
  private element: HTMLElement;
  private callbacks: RecordingPrepCallbacks;
  private checkSerial: number = 0;

  private statusIcon: HTMLElement;
  private statusText: HTMLElement;
  private errorBox: HTMLElement;
  private confirmBtn: HTMLButtonElement;
  private retryBtn: HTMLButtonElement;

  constructor(callbacks: RecordingPrepCallbacks) { ... }

  public open(): void {
    this.element.classList.add('open');
    void this.runCheck();
  }

  public close(): void {
    this.checkSerial++; // 使进行中的检测结果失效
    this.element.classList.remove('open');
  }

  private async runCheck(): Promise<void> {
    const serial = ++this.checkSerial;
    this.setStatus('checking');
    try {
      await this.callbacks.checkMicrophone();
      if (serial !== this.checkSerial) return;
      this.setStatus('ready');
    } catch (err) {
      if (serial !== this.checkSerial) return;
      this.setStatus('error', err instanceof Error ? err.message : String(err));
    }
  }

  private setStatus(status: MicStatus, errorMsg = ''): void { ... }
}
```

