import type { IAudioInputPort, AcousticFrameListener, StateChangeListener } from '../../ports/IAudioInputPort.js';
import { FeatureExtractor } from '../../core/algorithms/FeatureExtractor.js';

/**
 * Web Audio API 麦克风输入与声学特征分析适配器
 * 核心特性：只读取瞬时波形特征数值，流式分析后立即丢弃，绝不录制任何原始音频文件！
 */
export class WebAudioInputAdapter implements IAudioInputPort {
  private audioCtx: AudioContext | null = null;
  private mediaStream: MediaStream | null = null;
  private analyserNode: AnalyserNode | null = null;
  private sourceNode: MediaStreamAudioSourceNode | null = null;

  private featureExtractor: FeatureExtractor | null = null;
  private frameListeners: Set<AcousticFrameListener> = new Set();
  private stateListeners: Set<StateChangeListener> = new Set();

  private isRunning: boolean = false;
  private animationFrameId: number | null = null;
  private startTimestamp: number = 0;

  public async start(): Promise<void> {
    if (this.isRunning) return;

    try {
      // 1. 请求用户麦克风权限
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: false, // 保留原声起伏细节
          autoGainControl: false,  // 保留原声音量动态范围
        },
        video: false,
      });

      this.mediaStream = stream;

      // 2. 初始化 AudioContext
      const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.audioCtx = new AudioContextClass();
      if (this.audioCtx.state === 'suspended') {
        await this.audioCtx.resume();
      }

      // 3. 配置分析器节点
      this.analyserNode = this.audioCtx.createAnalyser();
      this.analyserNode.fftSize = 2048;
      this.analyserNode.smoothingTimeConstant = 0.4;

      this.sourceNode = this.audioCtx.createMediaStreamSource(stream);
      this.sourceNode.connect(this.analyserNode);

      // 4. 初始化特征提取器
      this.featureExtractor = new FeatureExtractor({
        sampleRate: this.audioCtx.sampleRate,
      });

      this.isRunning = true;
      this.startTimestamp = performance.now();
      this.notifyState(true);

      // 5. 启动循环分析
      this.loop();
    } catch (err) {
      this.stop();
      console.error('[WebAudioInputAdapter] Failed to start audio input:', err);
      throw new Error(`无法开启麦克风权限：${err instanceof Error ? err.message : String(err)}`);
    }
  }

  public stop(): void {
    if (!this.isRunning && !this.mediaStream) return;

    this.isRunning = false;

    if (this.animationFrameId !== null) {
      cancelAnimationFrame(this.animationFrameId);
      this.animationFrameId = null;
    }

    if (this.mediaStream) {
      this.mediaStream.getTracks().forEach(track => track.stop());
      this.mediaStream = null;
    }

    if (this.sourceNode) {
      this.sourceNode.disconnect();
      this.sourceNode = null;
    }

    if (this.audioCtx && this.audioCtx.state !== 'closed') {
      this.audioCtx.close().catch(() => {});
      this.audioCtx = null;
    }

    this.analyserNode = null;
    if (this.featureExtractor) {
      this.featureExtractor.reset();
    }

    this.notifyState(false);
  }

  public onFrame(listener: AcousticFrameListener): () => void {
    this.frameListeners.add(listener);
    return () => this.frameListeners.delete(listener);
  }

  public onStateChange(listener: StateChangeListener): () => void {
    this.stateListeners.add(listener);
    return () => this.stateListeners.delete(listener);
  }

  public isCapturing(): boolean {
    return this.isRunning;
  }

  private loop = (): void => {
    if (!this.isRunning || !this.analyserNode || !this.featureExtractor) return;

    const timeBuffer = new Float32Array(this.analyserNode.fftSize);
    const freqBuffer = new Uint8Array(this.analyserNode.frequencyBinCount);

    this.analyserNode.getFloatTimeDomainData(timeBuffer);
    this.analyserNode.getByteFrequencyData(freqBuffer);

    const relativeTime = performance.now() - this.startTimestamp;
    const frame = this.featureExtractor.extractFrame(timeBuffer, freqBuffer, relativeTime);

    // 广播物理特征（绝不缓存音频样本）
    this.frameListeners.forEach(listener => listener(frame));

    this.animationFrameId = requestAnimationFrame(this.loop);
  };

  private notifyState(capturing: boolean): void {
    this.stateListeners.forEach(fn => fn(capturing));
  }
}

