export interface RecordingPrepCallbacks {
  /** 探测麦克风权限与设备可用性，失败时抛出带用户可读信息的 Error */
  checkMicrophone: () => Promise<void>;
  /** 用户确认无误，正式进入结晶沉降录音 */
  onConfirm: () => void;
}

type MicStatus = 'checking' | 'ready' | 'error';

/**
 * 录音准备确认弹窗
 * 正式开始结晶沉降前的缓冲步骤：先检测麦克风权限可用性，
 * 并告知用户靠近说话、保持安静、仅提取脱敏声学特征，确认后才真正开始采集。
 */
export class RecordingPrepModal {
  private element: HTMLElement;
  private callbacks: RecordingPrepCallbacks;
  private checkSerial: number = 0;

  private statusRow: HTMLElement;
  private statusIcon: HTMLElement;
  private statusTitle: HTMLElement;
  private statusDesc: HTMLElement;
  private statusSpinner: HTMLElement;
  private errorBox: HTMLElement;
  private confirmBtn: HTMLButtonElement;
  private retryBtn: HTMLButtonElement;

  constructor(callbacks: RecordingPrepCallbacks) {
    this.callbacks = callbacks;
    this.element = document.createElement('div');
    this.element.className = 'modal-backdrop';

    this.element.innerHTML = `
      <div class="modal-card prep-card">
        <div class="modal-header">
          <div class="modal-title-wrap">
            <h3 class="modal-title">录音准备</h3>
            <span class="modal-subtitle">开始结晶沉降前，请确认以下事项</span>
          </div>
          <button class="close-btn" id="prep-close-btn" title="取消">&times;</button>
        </div>

        <div class="prep-mic-status" id="prep-mic-status">
          <span class="prep-mic-icon" id="prep-mic-icon">🎙️</span>
          <div class="prep-mic-text-box">
            <span class="prep-mic-title" id="prep-mic-title">正在检测麦克风权限...</span>
            <span class="prep-mic-desc" id="prep-mic-desc">浏览器可能会弹出授权请求，请选择「允许」</span>
          </div>
          <span class="prep-mic-spinner" id="prep-mic-spinner"></span>
        </div>

        <div class="prep-error-box" id="prep-error-box" style="display: none;"></div>

        <ul class="prep-tips-list">
          <li><span class="prep-tip-icon">📏</span><span>请<strong>靠近麦克风</strong>（约一拳距离），用正常音量自然说话</span></li>
          <li><span class="prep-tip-icon">🤫</span><span>请<strong>保持环境安静</strong]，避免背景音乐与他人交谈声混入</span></li>
          <li><span class="prep-tip-icon">🛡️</span><span>仅提取<strong>脱敏后的声学特征</strong>（音高、语速、停顿、能量起伏），绝不录制原始语音</span></li>
        </ul>

        <div class="modal-footer prep-footer">
          <div class="prep-privacy-note">🔒 特征即时演算后即弃，语音内容不出本机</div>
          <div class="prep-actions">
            <button class="btn-secondary" id="prep-cancel-btn">取消</button>
            <button class="btn-secondary" id="prep-retry-btn" style="display: none;">重新检测</button>
            <button class="btn-primary" id="prep-confirm-btn" disabled>检测中...</button>
          </div>
        </div>
      </div>
    `;

    this.statusRow = this.element.querySelector('#prep-mic-status') as HTMLElement;
    this.statusIcon = this.element.querySelector('#prep-mic-icon') as HTMLElement;
    this.statusTitle = this.element.querySelector('#prep-mic-title') as HTMLElement;
    this.statusDesc = this.element.querySelector('#prep-mic-desc') as HTMLElement;
    this.statusSpinner = this.element.querySelector('#prep-mic-spinner') as HTMLElement;
    this.errorBox = this.element.querySelector('#prep-error-box') as HTMLElement;
    this.confirmBtn = this.element.querySelector('#prep-confirm-btn') as HTMLButtonElement;
    this.retryBtn = this.element.querySelector('#prep-retry-btn') as HTMLButtonElement;

    this.initEvents();
  }

  public getElement(): HTMLElement {
    return this.element;
  }

  public open(): void {
    this.element.classList.add('open');
    void this.runCheck();
  }

  public close(): void {
    // 使进行中的异步检测结果失效，避免关闭后状态被回写
    this.checkSerial++;
    this.element.classList.remove('open');
  }

  private async runCheck(): Promise<void> {
    const serial = ++this.checkSerial;
    this.setStatus('checking');

    try {
      await this.callbacks.checkMicrophone();
      if (serial !== this.checkSerial) return;
      this.setStatus('ready');
    } catch (err) {
      if (serial !== this.checkSerial) return;
      this.setStatus('error', err instanceof Error ? err.message : String(err));
    }
  }

  private setStatus(status: MicStatus, errorMsg: string = ''): void {
    this.statusRow.classList.remove('ok', 'error');
    this.errorBox.style.display = 'none';
    this.retryBtn.style.display = 'none';

    if (status === 'checking') {
      this.statusIcon.textContent = '🎙️';
      this.statusTitle.textContent = '正在检测麦克风权限...';
      this.statusDesc.textContent = '浏览器可能会弹出授权请求，请选择「允许」';
      this.statusSpinner.style.display = 'inline-block';
      this.confirmBtn.disabled = true;
      this.confirmBtn.textContent = '检测中...';
    } else if (status === 'ready') {
      this.statusRow.classList.add('ok');
      this.statusIcon.textContent = '✅';
      this.statusTitle.textContent = '麦克风就绪';
      this.statusDesc.textContent = '设备检测通过，确认下方提示后即可开始';
      this.statusSpinner.style.display = 'none';
      this.confirmBtn.disabled = false;
      this.confirmBtn.textContent = '开始结晶沉降';
    } else {
      this.statusRow.classList.add('error');
      this.statusIcon.textContent = '⚠️';
      this.statusTitle.textContent = '麦克风不可用';
      this.statusDesc.textContent = '请根据下方提示处理后重新检测';
      this.statusSpinner.style.display = 'none';
      this.errorBox.textContent = errorMsg;
      this.errorBox.style.display = 'block';
      this.retryBtn.style.display = 'inline-flex';
      this.confirmBtn.disabled = true;
      this.confirmBtn.textContent = '无法开始';
    }
  }

  private initEvents(): void {
    this.element.querySelector('#prep-close-btn')?.addEventListener('click', () => this.close());
    this.element.querySelector('#prep-cancel-btn')?.addEventListener('click', () => this.close());
    this.element.addEventListener('click', (e) => {
      if (e.target === this.element) this.close();
    });

    this.retryBtn.addEventListener('click', () => {
      void this.runCheck();
    });

    this.confirmBtn.addEventListener('click', () => {
      if (this.confirmBtn.disabled) return;
      this.close();
      this.callbacks.onConfirm();
    });
  }
}

